# Create Library Websites with its custom icon and open Edge's default-browser settings.
# Run while signed into the Windows account customers use.
$ErrorActionPreference = 'Stop'

try {
    # Request administrator access if needed.
    $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
    $principal = New-Object Security.Principal.WindowsPrincipal($identity)
    if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
        $powershell = "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe"
        if ([Environment]::Is64BitOperatingSystem -and -not [Environment]::Is64BitProcess) {
            $powershell = "$env:SystemRoot\Sysnative\WindowsPowerShell\v1.0\powershell.exe"
        }
        $arguments = '-NoProfile -ExecutionPolicy Bypass -File "{0}"' -f $PSCommandPath
        $process = Start-Process $powershell -ArgumentList $arguments -Verb RunAs -Wait -PassThru
        exit $process.ExitCode
    }

    # Find Microsoft Edge.
    $edge = "${env:ProgramFiles(x86)}\Microsoft\Edge\Application\msedge.exe"
    if (-not (Test-Path -LiteralPath $edge)) {
        $edge = "$env:ProgramFiles\Microsoft\Edge\Application\msedge.exe"
    }
    if (-not (Test-Path -LiteralPath $edge)) { throw 'Microsoft Edge was not found.' }

    # Store the bundled icon on the PC so it still works after removing the USB.
    $iconFolder = Join-Path $env:ProgramData 'PAELibraries\Icons'
    [void](New-Item -ItemType Directory -Path $iconFolder -Force)
    $iconPath = Join-Path $iconFolder 'LibraryWebsites.ico'
    $iconData = @'
