    [IO.File]::WriteAllBytes($iconPath, [Convert]::FromBase64String($iconData))

    # Create the shortcut on the Public Desktop, visible to all users.
    $desktop = [Environment]::GetFolderPath('CommonDesktopDirectory')
    $shell = New-Object -ComObject WScript.Shell
    $shortcut = $shell.CreateShortcut((Join-Path $desktop 'Library Websites.lnk'))
    $shortcut.TargetPath = $edge
    $shortcut.Arguments = '"https://s3.ap-southeast-2.amazonaws.com/auprod.cloudnine.envisionware.net/libraries/55/content/pae-public-pc-welcome.html"'
    $shortcut.IconLocation = "$iconPath,0"
    $shortcut.Description = 'Open useful websites with PAE Libraries'
    $shortcut.Save()
    # Remove the previous shortcut only if it points to this same landing page.
    $oldPath = Join-Path $desktop 'Library favourites.lnk'
    if (Test-Path -LiteralPath $oldPath) {
        $oldShortcut = $shell.CreateShortcut($oldPath)
        if ($oldShortcut.TargetPath -ieq $edge -and $oldShortcut.Arguments -ceq $shortcut.Arguments) {
            Remove-Item -LiteralPath $oldPath
        }
    }
    Write-Output 'Created: Library Websites, with its custom icon. It opens directly in Edge.' 

    # Default-browser selection belongs to the customer account, not System.
    $signedInUser = (Get-CimInstance Win32_ComputerSystem).UserName
    if ([Diagnostics.Process]::GetCurrentProcess().SessionId -eq 0 -or $identity.Name -ine $signedInUser) {
        Write-Output 'Shortcut installed. To finish, sign into the customer account and select Microsoft Edge in Settings > Apps > Default apps.'
        exit 2
    }

    # Windows requires the user to click Set default on standalone PCs.
    Start-Process 'ms-settings:defaultapps?registeredAppMachine=Microsoft%20Edge'
    Write-Output 'Click Set default for Microsoft Edge in the Settings window.'
    exit 2  # The browser choice still needs the user's click.
} catch {
    Write-Error -Message $_.Exception.Message -ErrorAction Continue
    exit 1
}
